<script setup lang="ts">
import { computed, ref } from 'vue'
import { onShow, onHide, onUnload } from '@dcloudio/uni-app'
import AppCard from '../../components/AppCard.vue'
import { consultationRepository as api } from '../../services/api/consultation'
import type { ConsultationMode, ConsultationRequestV2 } from '../../types/consultation'
import { uniApi as uni } from '../../services/platform/uni'
const hasBloodTest = ref(false); const loading = ref(true); const busy = ref(false); const error = ref(''); const requests = ref<ConsultationRequestV2[]>([]); const selectedMode = ref<ConsultationMode>('immediate_text'); let timer: ReturnType<typeof setInterval> | undefined
const current = computed(() => requests.value[0])
async function load() { try { const [eligibility, items] = await Promise.all([api.eligibility(), api.consultationRequests()]); hasBloodTest.value = eligibility.hasBloodTest; requests.value = items; error.value = '' } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
function stop() { if (timer) clearInterval(timer); timer = undefined }
onShow(() => { load(); stop(); timer = setInterval(load, 5000) }); onHide(stop); onUnload(stop)
async function submit() { if (!hasBloodTest.value) { uni.navigateTo({ url: '/pages/health-centers/index' }); return } if (busy.value) return; busy.value = true; try { const item = await api.createRequest(selectedMode.value); requests.value = [item, ...requests.value]; uni.navigateTo({ url: `/pages/consultation/waiting?requestId=${item.id}` }) } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
</script>
<template><view class="page consult-entry"><view class="entry-head"><text class="eyebrow">健康服务</text><text class="title">发起咨询</text><text class="subtitle">平台会为你匹配合适的健康管理师，配对后进入专属咨询房间。</text></view><AppCard v-if="error" class="error"><text class="danger">{{ error }}</text><button class="retry" @click="load">重新连接</button></AppCard><AppCard v-if="!loading && !hasBloodTest" class="guide"><view class="guide-icon">!</view><view class="guide-copy"><text class="guide-title">开始前需要血液检测</text><text class="muted">为了让健管师结合真实指标沟通，请先完成指定检查并上传报告。</text></view><button class="btn secondary" @click="uni.navigateTo({ url: '/pages/health-centers/index' })">查看指定体检中心</button></AppCard><template v-else><view class="section-title">选择咨询方式</view><view class="mode-list"><AppCard :class="['mode-card',{selected:selectedMode==='immediate_text'}]" @click="selectedMode='immediate_text'"><view class="mode-icon chat">⌁</view><view class="mode-copy"><text class="mode-title">文字咨询</text><text class="muted">进入房间后随时打字沟通</text></view><text class="radio">{{ selectedMode === 'immediate_text' ? '✓' : '○' }}</text></AppCard><AppCard class="mode-card disabled-mode"><view class="mode-icon voice">⌕</view><view class="mode-copy"><text class="mode-title">语音咨询</text><text class="muted">语音功能暂未开启，请先使用文字沟通</text></view><text class="disabled-label">暂未开启</text></AppCard></view><button class="btn submit" :disabled="busy" @click="submit">{{ busy ? '正在提交…' : '立即发起咨询' }}</button></template><view class="section-title progress-title">我的咨询</view><AppCard v-if="!current" class="empty"><text class="empty-icon">⌁</text><text class="empty-title">还没有进行中的咨询</text><text class="muted">发起后可以在这里查看配对进度</text></AppCard><AppCard v-else class="progress-card" @click="current.conversationId && uni.navigateTo({ url: `/pages/consultation/index?conversationId=${current.conversationId}` })"><view class="progress-head"><text class="progress-name">{{ current.consultantName || '等待平台配对' }}</text><text class="tag">{{ current.status === 'queued' ? '等待配对' : current.status === 'assigned' ? '待确认' : current.status === 'in_progress' ? '咨询中' : current.status }}</text></view><text class="muted">{{ current.status === 'queued' ? '平台正在为你安排健康管理师' : current.conversationId ? '点击进入咨询房间' : '等待健管师确认' }}</text></AppCard></view></template>
<style scoped>.consult-entry{padding-top:34rpx;padding-bottom:60rpx;background:#fffaf6}.entry-head{padding:0 2rpx 14rpx}.eyebrow{display:block;color:#b37a57;font-size:22rpx;letter-spacing:2rpx}.title{display:block;margin-top:8rpx;color:#2a201c;font-size:42rpx;font-weight:800}.entry-head .subtitle{margin-top:12rpx;line-height:1.6}.error{padding:20rpx;background:#fff0ed}.error .danger{display:block}.retry{width:100%;height:64rpx;margin-top:14rpx;line-height:64rpx;color:#c8652a;background:#fff}.guide{display:flex;flex-wrap:wrap;align-items:flex-start;padding:24rpx;background:#fff0e5}.guide-icon{width:52rpx;height:52rpx;margin-right:14rpx;border-radius:18rpx;color:#fff;background:#d96b2b;font-size:31rpx;line-height:52rpx;text-align:center;font-weight:800}.guide-copy{flex:1}.guide-title{display:block;color:#9f5428;font-size:27rpx;font-weight:800}.guide-copy .muted{margin-top:9rpx;color:#8a6857;line-height:1.55}.guide .btn{margin-top:20rpx}.section-title{margin:30rpx 2rpx 15rpx;color:#2a201c;font-size:30rpx;font-weight:800}.mode-list{display:flex;flex-direction:column;gap:14rpx}.mode-card{display:flex;align-items:center;margin-top:0;padding:22rpx;border:2rpx solid transparent}.mode-card.selected{border-color:#df8755;background:#fff8f2;box-shadow:0 8rpx 24rpx rgba(202,96,42,.1)}.mode-icon{display:flex;align-items:center;justify-content:center;width:64rpx;height:64rpx;margin-right:16rpx;border-radius:21rpx;color:#d96b2b;background:#fff0e5;font-size:36rpx}.mode-icon.voice{color:#fff;background:#d96b2b}.mode-copy{flex:1}.mode-title{display:block;font-size:27rpx;font-weight:800}.mode-copy .muted{margin-top:6rpx}.radio{color:#d96b2b;font-size:31rpx}.submit{margin-top:22rpx}.btn[disabled]{opacity:.55}.progress-title{margin-top:36rpx}.progress-card{padding:24rpx}.progress-head{display:flex;align-items:center;justify-content:space-between}.progress-name{font-size:27rpx;font-weight:800}.tag{padding:8rpx 13rpx;color:#c8652a;border-radius:12rpx;background:#fff0e5;font-size:19rpx}.progress-card .muted{margin-top:12rpx}.empty{text-align:center;padding:42rpx 24rpx}.empty-icon{display:block;color:#d96b2b;font-size:52rpx}.empty-title{display:block;margin-top:10rpx;font-size:27rpx;font-weight:800}.empty .muted{margin-top:8rpx}</style>
